let lang = 'es';
/** The browser's preferred language if it is one of ours (Spanish or English), otherwise English. */
export const browserLang = () => (navigator.languages || [navigator.language]).map((l) => String(l).slice(0, 2).toLowerCase()).find((l) => T[l]) || 'en';
export const setLang = (l) => { lang = T[l] ? l : browserLang(); document.documentElement.lang = lang; };
export const getLang = () => lang;
export const LANGS = { es: 'Español', en: 'English' };
export function t(key, ...args) {
  const s = T[lang][key] ?? T.es[key] ?? key;
  return args.length ? s.replace(/\{(\d)\}/g, (_, i) => args[i]) : s;
}
